(function(){document.querySelectorAll('.fx-type .w').forEach(function(el){var ws=JSON.parse(el.getAttribute('data-words')),wi=0,ci=ws[0].length,del=true;
function sp(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--speed'))||1}
function tick(){var w=ws[wi];if(del){ci--;el.textContent=w.slice(0,ci);if(ci<=0){del=false;wi=(wi+1)%ws.length}return setTimeout(tick,45/sp())}
ci++;el.textContent=ws[wi].slice(0,ci);if(ci>=ws[wi].length){del=true;return setTimeout(tick,1500/sp())}setTimeout(tick,85/sp())}
setTimeout(tick,1400)})})();
